  /* ---------- ana test: ünite başına 10 ---------- */
  Q7.tdb = [
    {u:"ÜNİTE 1 · İslam ve Ahlak", q:"Kitaba göre Allah'a karşı sorumluluklarımızın başında hangisi gelir?", o:["Akrabaları ziyaret etmek","O'na iman etmek","Komşuları gözetmek","Kur'an'ı ezberlemek"], a:1,
     w:"Allah'a karşı yerine getirilmesi gereken sorumlulukların başında O'na iman etmek gelir: varlığını, birliğini; eşi, benzeri ve ortağı olmadığını kabul etmek."},
    {u:"ÜNİTE 1 · İslam ve Ahlak", q:"Kişinin kendi davranışlarının sonuçlarını üstlenmesine ne denir?", o:["İhlas","Teslimiyet","Zikir","Sorumluluk"], a:3,
     w:"Sorumluluk budur. Kur'an'da “İnsan, kendisinin başıboş bırakılacağını mı zanneder.” (Kıyamet suresi 36) buyrulur."},
    {u:"ÜNİTE 1 · İslam ve Ahlak", q:"“... Benim namazım, (her türlü) ibadetim, hayatım ve ölümüm, hepsi âlemlerin Rabbi olan Allah içindir.” (Enam suresi 162)\n\nBu ayet Allah'a karşı hangi sorumluluğumuzla ilgilidir?", o:["İhlaslı olmak","Peygamberimize salavat getirmek","Komşuların hakkını gözetmek","Kur'an'ı tane tane okumak"], a:0,
     w:"İhlas, bütün söz ve davranışlarda yalnızca Allah'ın rızasını gözetmektir. Ayet, hayatın tamamının Allah için olması gerektiğini anlatır."},
    {u:"ÜNİTE 1 · İslam ve Ahlak", q:"Sahip olunan mal varlığının şükrü nasıl yerine getirilir?", o:["Daha çok mal biriktirerek","Yalnızca “Teşekkür ederim.” diyerek","Zekât ve sadaka vererek","Malı kimseye göstermeyerek"], a:2,
     w:"Her nimetin şükrü kendi cinsinden yapılır. Malın şükrü zekât ve sadaka vermektir; “Teşekkür ederim.” demek dilin şükrüdür."},
    {u:"ÜNİTE 1 · İslam ve Ahlak", q:"Peygamberimizi anmak ve ona selam göndermek için okunan dualara ne ad verilir?", o:["Zikir","Tesbih","Besmele","Salavat"], a:3,
     w:"Salavat getirmek Peygamberimize karşı sorumluluklarımızdandır. Namazdaki oturuşlarda Salli–Barik duaları okunur."},
    {u:"ÜNİTE 1 · İslam ve Ahlak", q:"“Ey iman edenler! Seslerinizi, Peygamber'in sesinin üstüne yükseltmeyin...” (Hucurat suresi 2)\n\nBu ayet Peygamberimize karşı hangi sorumluluğumuzu vurgular?", o:["Sünnetini ezberlemek","Ona saygı göstermek","Kur'an'ı ondan öğrenmek","Onun doğduğu şehri ziyaret etmek"], a:1,
     w:"Peygamberimize duyulan sevgi ve bağlılık ona saygı duymayı da gerektirir; ayet bütün Müslümanların ona saygı göstermesi gerektiğini bildirir."},
    {u:"ÜNİTE 1 · İslam ve Ahlak", q:"Kitaba göre Kur'an-ı Kerim'e karşı sorumluluklarımızın başında hangisi gelir?", o:["Onu başka dillere çevirmek","Onu güzel sesle okumak","Ona iman etmek","Onu güzel bir kılıfta saklamak"], a:2,
     w:"Kur'an'a karşı sorumlulukların başında ona iman etmek gelir: Allah tarafından Peygamberimize vahyedildiğine ve içeriğinin tümüyle doğru olduğuna inanmak."},
    {u:"ÜNİTE 1 · İslam ve Ahlak", q:"“... Verdiğiniz sözü de yerine getirin. Çünkü verilen söz, sorumluluğu gerektirir.” (İsra suresi 34)\n\nBu ayet topluma karşı hangi sorumluluğumuzla ilgilidir?", o:["Doğruluk","Yardımlaşma","Akrabayı gözetme","İyiliği tavsiye etme"], a:0,
     w:"Kitaba göre verdiği sözü tutmak ve tutamayacağı sözü vermemek doğru kimselerin özelliğidir."},
    {u:"ÜNİTE 1 · İslam ve Ahlak", q:"Akrabalık ilişkilerini ve akrabayı gözetmeyi anlatan kavram hangisidir?", o:["İhlas","Sılayırahim","Ensar","Salavat"], a:1,
     w:"Sıla “bağ, ilişki”, rahim “akrabalık bağı” demektir; sılayırahim akrabalık ilişkileridir."},
    {u:"ÜNİTE 1 · İslam ve Ahlak", q:"“Her türlü eksiklikten ve kusurdan uzak olan, kullarına güvenlik ve esenlik veren” anlamındaki isim hangisidir?", o:["Aziz","Rahman","Rahim","Selam"], a:3,
     w:"Selam sözlükte güven, esenlik, emniyet ve huzur demektir. Bu ismi bilen Müslüman güvenilir olmaya çalışır ve selamı yayar."},
    {u:"ÜNİTE 2 · İslam ve Temizlik", q:"“Temizlik imanın yarısıdır.” hadisi aşağıdakilerden hangisini vurgular?", o:["Temizliğin yalnızca ibadette gerektiğini","Temizlik ile iman arasında sıkı bir bağ olduğunu","İmanın yalnızca temizlikten ibaret olduğunu","Temizliğin sadece beden için önemli olduğunu"], a:1,
     w:"Peygamberimiz bu hadisle temizlik ile iman arasındaki bağa dikkat çekmiştir. Temizlik bazı ibadetlerin şartı olduğu gibi Müslümanın hayatının da vazgeçilmez bir parçasıdır."},
    {u:"ÜNİTE 2 · İslam ve Temizlik", q:"Aşağıdakilerden hangisi hükmi temizliğe örnektir?", o:["Tırnakları kesmek","Sınıfı süpürmek","Tövbe etmek","Abdest almak"], a:3,
     w:"Hükmi temizlik, ibadete engel olan abdestsizlik hâlinden abdest ve gusülle arınmaktır. Tırnak kesmek ve sınıfı süpürmek maddi, tövbe etmek manevi temizliktir."},
    {u:"ÜNİTE 2 · İslam ve Temizlik", q:"Namaz kılınacak yerin, elbisenin ve bedenin dinen pis sayılan şeylerden temizlenmesine ne ad verilir?", o:["Necasetten taharet","Hadesten taharet","Manevi temizlik","Teyemmüm"], a:0,
     w:"Dinen pis sayılan şeylere necaset denir. Beden, elbise ve ibadet yerini bunlardan temizlemek bazı ibadetlerin şartıdır. Hadesten taharet ise abdestsizlik hâlinden arınmaktır."},
    {u:"ÜNİTE 2 · İslam ve Temizlik", q:"Aşağıdakilerden hangisi abdestin farzlarından biri DEĞİLDİR?", o:["Yüzü yıkamak","Başın dörtte birini mesh etmek","Kulakları ve enseyi mesh etmek","Ayakları topuklarla beraber yıkamak"], a:2,
     w:"Abdestin farzı dörttür: yüzü yıkamak, elleri ve kolları dirseklerle beraber yıkamak, başın dörtte birini mesh etmek, ayakları topuklarla beraber yıkamak. Kulakları ve enseyi mesh etmek abdestin alınışında vardır ama farzlardan değildir."},
    {u:"ÜNİTE 2 · İslam ve Temizlik", q:"Abdest alıp mest giyen bir kişi, daha sonra yeniden abdest alırken ayaklarını yıkamak yerine ne yapabilir?", o:["Mestlerinin üzerine mesh eder.","Ayaklarını toprağa sürüp mesh eder.","Yalnızca topuklarını ıslatır.","Ayaklarını yalnızca bir kez yıkar."], a:0,
     w:"Mest üzerine mesh, İslam'ın ibadetlerde getirdiği kolaylıklardandır. Mest, ayakları bileklerin üstüne kadar kapatan, deri ve benzeri maddeden yapılmış ince bir ayakkabıdır."},
    {u:"ÜNİTE 2 · İslam ve Temizlik", q:"Guslün farzları aşağıdakilerin hangisinde doğru verilmiştir?", o:["Yüzü, elleri ve ayakları yıkamak","Ağzı, burnu ve bütün bedeni yıkamak","Ağzı ve burnu yıkamak, başı mesh etmek","Bütün bedeni yıkamak, kulakları mesh etmek"], a:1,
     w:"Guslün farzı üçtür: ağzı yıkamak, burnu yıkamak ve bütün bedeni yıkamak. Gusülde ağız ve burun içleri dâhil hiç kuru yer kalmadan bütün vücut yıkanır."},
    {u:"ÜNİTE 2 · İslam ve Temizlik", q:"Su bulunmadığında ya da kullanılamadığında abdestin ve guslün yerine geçen temizliğe ne ad verilir?", o:["Boy abdesti","Tövbe","Teyemmüm","Necasetten taharet"], a:2,
     w:"Teyemmüm toprak veya toprak cinsi bir maddeyle yapılır. Allah'ın ibadetlerde verdiği bir kolaylıktır (Maide suresi 6). Boy abdesti guslün diğer adıdır; tövbe ise hatalardan dönüp Allah'tan af dilemektir."},
    {u:"ÜNİTE 2 · İslam ve Temizlik", q:"Su bulunmadığında toprakla yapılan temizliğin farzları hangi seçenekte birlikte verilmiştir?", o:["Yüzü yıkamak, başın dörtte birini mesh etmek","Niyet etmek, yüzü ve kolları toprakla mesh etmek","Euzübesmele çekmek, ayakları toprakla mesh etmek","Elleri toprağa sürmek, başı ve kulakları mesh etmek"], a:1,
     w:"Bu temizliğin farzı ikidir: niyet etmek ve elleri temiz toprağa sürerek yüzü ve kolları mesh etmek. Euzübesmele alınışında vardır ama farzlardan değildir."},
    {u:"ÜNİTE 2 · İslam ve Temizlik", q:"“Kim (Allah'ın huzuruna) iyilikle gelirse ona getirdiğinin on katı vardır...” (Enam suresi 160)\n\nBu ayette Allah'ın hangi isminin anlamı öne çıkar?", o:["Kuddûs","Tevvâb","Selam","Kerim"], a:3,
     w:"Allah iyiliklere fazlasıyla karşılık verir. Kerim yarattıklarını rızıklandıran, nimetlerini karşılıksız veren, cömert, büyük ve en şerefli demektir."},
    {u:"ÜNİTE 2 · İslam ve Temizlik", q:"Peygamberimiz, ıssız bir çölde kaybettiği devesini bulan kişi nasıl sevinirse Allah'ın da kullarının tövbesine öyle sevindiğini bildirmiştir.\n\nBu hadis Allah'ın hangi ismiyle en çok ilgilidir?", o:["Tevvâb","Aziz","Kuddûs","Selam"], a:0,
     w:"Tevvâb, günahlarından pişman olan kullarını bağışlayan ve tövbelerini çokça kabul eden demektir. Allah tövbe kapısını kullarına alabildiğine açık tutar (Tevbe suresi 104)."}
  ];

  /* ---------- havuz: yalnız Yanlışlarım'da çıkar, ünite başına 5 ---------- */
  H7.tdb = [
    {u:"ÜNİTE 1 · İslam ve Ahlak", q:"“Dua, ibadetin özüdür.” hadisine göre dua için ne söylenebilir?", o:["Kulluğun en özlü ifadesidir.","Yalnızca zor günlerde yapılır.","Sadece camide yapılabilir.","Yalnızca sesli yapılmalıdır."], a:0,
     w:"Dua Allah ile kul arasındaki iletişim yoludur; Peygamberimiz onu ibadetin özü saymıştır."},
    {u:"ÜNİTE 1 · İslam ve Ahlak", q:"“Sünnet” kelimesinin sözlük anlamı hangisidir?", o:["Samimiyet, içtenlik","Bağ, ilişki","Yol, gidişat, metot","Güven, esenlik, huzur"], a:2,
     w:"Sünnet sözlükte yol, gidişat, metot demektir. “Güven, esenlik” Selam'ın, “samimiyet” ihlasın, “bağ, ilişki” sılanın anlamıdır."},
    {u:"ÜNİTE 1 · İslam ve Ahlak", q:"Kur'an-ı Kerim Peygamberimize yaklaşık kaç yılda indirilmiştir?", o:["On","Kırk","Beş","Yirmi üç"], a:3,
     w:"Kur'an yaklaşık yirmi üç yıllık bir zaman diliminde indirilen son ilahi kitaptır."},
    {u:"ÜNİTE 1 · İslam ve Ahlak", q:"“Bir kötülük gören kişi, eli ile değiştirmeye gücü yetiyorsa onu eli ile değiştirsin...” hadisi topluma karşı hangi sorumluluğumuzla ilgilidir?", o:["Akrabalarla görüşmek","İyiliği tavsiye edip kötülükten sakındırmak","Komşuları ziyaret etmek","Büyüklere yer vermek"], a:1,
     w:"Toplumun ahlak düzenini korumak için iyiliği emretmek ve kötülükten sakındırmak herkesin sorumluluğudur."},
    {u:"ÜNİTE 1 · İslam ve Ahlak", q:"“Bütün canlılara merhamet eden, her türlü nimeti sürekli veren” anlamındaki isim hangisidir?", o:["Selam","Kuddûs","Rahman","Aziz"], a:2,
     w:"Rahman ismi Allah'ın bütün varlıklara rahmetinin göstergesidir; besmelede de geçer."},
    {u:"ÜNİTE 2 · İslam ve Temizlik", q:"Peygamberimiz döneminde erak denen bir ağacın dallarından elde edilip ağız ve diş temizliğinde kullanılan dal parçasına ne ad verilir?", o:["Misvak","Mest","Seccade","Tesbih"], a:0,
     w:"Hz. Aişe, Peygamberimizin eve gelince ilk iş misvakla dişlerini temizlediğini aktarır. Bu, onun ağız ve diş temizliğine verdiği önemi gösterir."},
    {u:"ÜNİTE 2 · İslam ve Temizlik", q:"Abdesti bozulan Ali, yeniden abdest alana kadar namaz kılamaz ve Kur'an okuyamaz.\n\nAli'nin içinde bulunduğu abdestsizlik hâli hangi kavramla ifade edilir?", o:["Necaset","Hades","Nezafet","Teyemmüm"], a:1,
     w:"Hades, ibadetleri yerine getirmeye engel olan abdestsizlik hâlidir. Bu hâlden abdest ve gusül alınarak temizlenilir."},
    {u:"ÜNİTE 2 · İslam ve Temizlik", q:"Yalan, dedikodu, kıskançlık ve büyüklenmek gibi kötü huylar insanı manevi olarak kirletir.\n\nKitaba göre bu kirlerden arınmanın yolu nedir?", o:["Elbiseyi temiz tutmak","Dişleri fırçalamak","Evin önünü süpürmek","Tövbe etmek"], a:3,
     w:"Manevi temizlik kalbin kötü duygulardan temizlenmesidir. Kur'an'da “Allah çok tövbe edenleri ve içi dışı temiz olanları sever.” (Bakara suresi 222) buyrulur."},
    {u:"ÜNİTE 2 · İslam ve Temizlik", q:"Aşağıdakilerden hangisi kitaba göre abdesti bozar?", o:["Ağız dolusu kusmak","Abdestliyken mest giymek","Kur'an dinlemek","Saçları taramak"], a:0,
     w:"Kitapta abdesti bozan durumlar şunlardır: idrar ve dışkı yollarından bir şey çıkması, vücuttan kan ya da irin çıkması, uyuma ve bayılma, ağız dolusu kusmak, namazda yanındakilerin işiteceği kadar gülmek."},
    {u:"ÜNİTE 2 · İslam ve Temizlik", q:"Sözlükte “tertemiz, pak, kusurdan arınmış” anlamına gelen ve yalnızca Allah'a ithaf edilebilen isim hangisidir?", o:["Kerim","Selam","Kuddûs","Tevvâb"], a:2,
     w:"Kuddûs, her türlü eksiklikten ve hatadan uzak olan, kemal ve güzellik sahibi demektir. Bu isim yalnızca Allah için kullanılır (Haşr suresi 23)."}
  ];

  /* ---------- ek çalışma seti ----------
     "EK · 1. Yazılı Hazırlık" (25): Allah'a karşı (5), Peygamberimize karşı (5),
     Kur'an'a karşı (4), topluma karşı (5), Aziz–Rahman–Selam (6). */
  EKC7.tdb = [
    {u:"EK · 1. Yazılı Hazırlık", q:"Mevsimlerin birbirini izlemesi, çiçeklerin rengârenk açması, kuşların gökyüzünde uçması kâinatta mükemmel bir düzen olduğunu gösterir.\n\nBu düzen en çok neyin işaretidir?", o:["Allah'ın varlığının ve birliğinin","Her şeyin kendiliğinden oluştuğunun","Doğanın kimseye ihtiyaç duymadığının","İnsanların doğayı yönettiğinin"], a:0,
     w:"Kâinattaki düzen Allah'ın varlığının ve birliğinin en önemli işaretidir: “Eğer yerde ve gökte Allah'tan başka ilahlar olsaydı kesinlikle ikisinin de düzeni bozulurdu...” (Enbiya suresi 22)"},
    {u:"EK · 1. Yazılı Hazırlık", q:"“Ben cinleri ve insanları ancak bana kulluk etsinler diye yarattım.” (Zariyat suresi 56)\n\nBu ayete göre ibadet insan için neyi ifade eder?", o:["Boş zamanını değerlendirme yolunu","Yaratılış amacını","İsteğe bağlı bir uğraşı","Ailesinden gördüğü bir geleneği"], a:1,
     w:"Allah'ın kulları üzerindeki hakkı diye tanımlanan ibadet, insanın yaratılış amacını ifade eder."},
    {u:"EK · 1. Yazılı Hazırlık", q:"Ali gün içinde Allah'ı sık sık anar, O'nun yüceliğini düşünür ve O'na gönülden yönelir.\n\nAli'nin bu davranışı Allah'a karşı hangi sorumluluğuyla ilgilidir?", o:["Teslimiyet","Sılayırahim","Salavat","Zikir"], a:3,
     w:"Zikir Allah'ı anmak ve her an hatırda tutmaktır: “... Biliniz ki kalpler ancak Allah'ı anmakla huzur bulur.” (Rad suresi 28)"},
    {u:"EK · 1. Yazılı Hazırlık", q:"Aşağıdakilerden hangisi “bedenin şükrü”ne örnektir?", o:["Allah'ın emirlerini yapıp yasaklarından uzak durmak","“Şükürler olsun.” demek","Zekât ve sadaka vermek","Nimetlerin bilincinde olup şükran duymak"], a:0,
     w:"Bedenin şükrü emirleri yapıp yasaklardan uzak durmaktır. “Şükürler olsun.” demek dilin, zekât vermek malın, şükran duymak kalbin şükrüdür."},
    {u:"EK · 1. Yazılı Hazırlık", q:"Zehra yaptığı iyilikleri kimse görmese de, övülmek için değil yalnızca Allah rızası için yapar.\n\nZehra'nın bu tutumu hangi kavramla açıklanır?", o:["Salavat","Teslimiyet","İhlas","Sılayırahim"], a:2,
     w:"İhlas samimiyet demektir: bütün söz ve davranışlarda yalnızca Allah'ın rızasını gözetmek."},

    {u:"EK · 1. Yazılı Hazırlık", q:"Kitaba göre Peygamberimize karşı sorumluluklarımızın başında hangisi gelir?", o:["Ona salavat getirmek","Onun sünnetine uymak","Onu herkesten çok sevmek","Onun peygamber olduğuna iman etmek"], a:3,
     w:"Seçeneklerin hepsi Peygamberimize karşı sorumluluktur; kitaba göre bunların başında onun Allah'ın peygamberi olduğuna iman etmek gelir. Bu iman, ona bildirilen her şeyi kabul etmeyi de gerektirir."},
    {u:"EK · 1. Yazılı Hazırlık", q:"Peygamberimiz bir konuda hüküm verdiğinde Müslümanlar bunu itiraz etmeden, içlerinde hiçbir sıkıntı duymadan benimser.\n\nBu tutum Peygamberimize karşı hangi sorumluluğumuzdur?", o:["Komşuları gözetmek","Ona samimiyetle teslim olmak","Ona salavat getirmek","Kur'an'ı tane tane okumak"], a:1,
     w:"Teslimiyet, Peygamberimizin tebliğ ettiği hükümlerin doğru olduğuna içtenlikle inanmak ve verdiği hükmü itiraz etmeden benimsemektir (Nisa suresi 65)."},
    {u:"EK · 1. Yazılı Hazırlık", q:"Peygamberimizin adı anıldığında söylenen “Sallallâhu aleyhi ve sellem” ifadesinin anlamı nedir?", o:["Allah yüceler yücesidir.","Allah'a hamdolsun.","Allah'ın salat ve selamı onun üzerine olsun.","Allah ondan razı olsun."], a:2,
     w:"Bu ifade bir salavattır. “Yüceler yücesi” anlamındaki söz ise Allah'ın adı anılınca söylenen “cellecelalüh”tür."},
    {u:"EK · 1. Yazılı Hazırlık", q:"Peygamberimiz “Herhangi biriniz beni babasından, evladından ve bütün insanlardan daha çok sevmedikçe iman etmiş olmaz.” buyurmuştur.\n\nBu hadis Peygamberimize karşı hangi sorumluluğumuzu anlatır?", o:["Onu herkesten çok sevmek","Ona salavat getirmek","Sünnetine uymak","Ona samimiyetle teslim olmak"], a:0,
     w:"Peygamberimizi herkesten çok sevmek hem ahlaki bir sorumluluk hem de imanın bir gereğidir: “Peygamber, müminlere kendi canlarından daha yakındır...” (Ahzab suresi 6)"},
    {u:"EK · 1. Yazılı Hazırlık", q:"Peygamberimiz bir işe besmeleyle başlar, insanlara selam verir, hastaları ziyaret eder, hediyeleşirdi.\n\nBu davranışları kendi hayatına taşıyan bir Müslüman hangi sorumluluğunu yerine getirir?", o:["Akrabayı gözetmek","Sünnetine uyup onu örnek almak","Ona salavat getirmek","Kur'an'ı tane tane okumak"], a:1,
     w:"Peygamberimizin örnek yaşantısı hayatın her alanında yol gösterir; onun sünnetine uymak ve onu örnek almak ona karşı sorumluluklarımızdandır."},

    {u:"EK · 1. Yazılı Hazırlık", q:"“... Kur'an'ı ağır ağır, tane tane oku.” (Müzzemmil suresi 4)\n\nBu ayete göre Kur'an nasıl okunmalıdır?", o:["Yalnızca ezberleyerek","Hızlıca bitirerek","Sadece başkasından dinleyerek","Acele etmeden, tane tane"], a:3,
     w:"Kur'an'ı okumak, ayetlerini özümsemek ve onlar üzerine düşünmek demektir."},
    {u:"EK · 1. Yazılı Hazırlık", q:"Kur'an'a iman eden bir Müslüman aşağıdakilerden hangisini kabul ETMEZ?", o:["Hükümlerinin yalnızca belli bir dönem için geçerli olduğunu","Allah tarafından Peygamberimize vahyedildiğini","Son ilahi kitap olduğunu","Değişmeden günümüze ulaştığını"], a:0,
     w:"Kur'an'ın hükümleri kıyamete kadar yaşayacak bütün insanlar için geçerlidir; hem bireysel hem toplumsal hayatı düzenler."},
    {u:"EK · 1. Yazılı Hazırlık", q:"“Kur'an okunduğu zaman ona kulak verip dinleyin ve susun ki size rahmet edilsin.” (Araf suresi 204)\n\nBu ayet Kur'an'a karşı hangi davranışı öğütler?", o:["Kur'an'ı yüksek sesle ezberlemek","Kur'an'ı başka kitaplarla karşılaştırmak","Okunurken ona hürmet edip dinlemek","Kur'an'ı yalnız başına okumak"], a:2,
     w:"Müslüman Kur'an'ı hem okurken hem dinlerken ona hürmet gösterir."},
    {u:"EK · 1. Yazılı Hazırlık", q:"Peygamberimiz “Sizin en hayırlınız, Kur'an'ı öğrenen ve öğretendir.” buyurmuştur.\n\nBu hadise göre Kur'an'a karşı neyi önemsemeliyiz?", o:["Yalnızca dinlemeyi","Sadece saklamayı","Yalnızca ezberlemeyi","Öğrenmeyi ve öğretmeyi"], a:3,
     w:"Peygamberimiz her gün Kur'an okumuş ve Müslümanlardan da Kur'an'ı hayatlarına katmalarını, öğrenip öğretmelerini istemiştir."},

    {u:"EK · 1. Yazılı Hazırlık", q:"“Doğruluk” kavramının anlamı aşağıdakilerden hangisidir?", o:["Herkese güler yüz göstermek","Gerçeği gözetip yalandan sakınmak","Allah'ı her an anmak","Akrabalık bağını sürdürmek"], a:1,
     w:"Doğruluk söz ve davranışlarda gerçeği gözetmek, yalandan sakınmaktır. Allah'ı her an anmak zikir, akrabalık bağını sürdürmek sılayırahimdir."},
    {u:"EK · 1. Yazılı Hazırlık", q:"“Ey iman edenler! Kendinizin veya anne babanızın ve akrabanızın aleyhine de olsa adaletten asla ayrılmayan ... kimseler olun...” (Nisa suresi 135)\n\nBu ayete göre bir Müslüman nasıl davranmalıdır?", o:["İşine geldiğinde adaletli olmalıdır.","Tanımadıklarına adil olmak zorunda değildir.","Kimin aleyhine olursa olsun adil olmalıdır.","Yalnızca akrabalarına adil davranmalıdır."], a:2,
     w:"Müslüman, şartlar ne olursa olsun söz ve davranışlarında adaleti gözetir; kul hakkına yol açacak davranışlardan kaçınır."},
    {u:"EK · 1. Yazılı Hazırlık", q:"Elif üzgün arkadaşını teselli ediyor, bildiği konuları ona anlatıyor, arkadaşı hastalanınca da ziyaretine gidiyor.\n\nElif'in bu davranışları topluma karşı hangi sorumluluğumuz kapsamındadır?", o:["Yardımlaşma","İhlas","Salavat","Teslimiyet"], a:0,
     w:"Yardımlaşmanın geniş bir anlamı vardır; yalnızca maddi yardım değil, bu davranışlar da yardımlaşmadır (Maide suresi 2)."},
    {u:"EK · 1. Yazılı Hazırlık", q:"Hicretten sonra Mekke'den gelen Müslümanlara yardım eden Medinelilere ne ad verilmiştir?", o:["Mümin","Ensar","Muhacir","Hanif"], a:1,
     w:"Ensar “yardım edenler, yardımcı olanlar” demektir. Peygamberimiz Mekkelilerle Medinelileri kardeş ilan etmiş, Medineliler onların sıkıntılarını hafifletmiştir."},
    {u:"EK · 1. Yazılı Hazırlık", q:"Peygamberimiz “Cebrail bana komşu hakkına saygı göstermeyi o kadar çok tavsiye etti ki komşunun komşuya mirasçı kılınacağını zannettim.” buyurmuştur.\n\nBu hadisten çıkarılabilecek en doğru sonuç hangisidir?", o:["Komşular birbirinin mirasçısıdır.","Komşularla yalnızca bayramlarda görüşülmelidir.","Komşuluk ilişkileri isteğe bağlıdır.","Komşu hakları dinimizde çok önemlidir."], a:3,
     w:"Hadis komşuya verilen değeri vurgular; komşuların mirasçı yapıldığını söylemez. Komşunun sevincini ve üzüntüsünü paylaşmak, hastalığında ziyaret etmek bu sorumluluğun gereğidir."},

    {u:"EK · 1. Yazılı Hazırlık", q:"Aziz isminin anlamı aşağıdakilerden hangisidir?", o:["Güç, kuvvet ve şeref sahibi","Kullarını kolayca affeden","Her şeyi bilen","Kullarına rızık veren"], a:0,
     w:"Aziz sözlükte eşi ve benzeri bulunmayacak kadar değerli, karşı konulamaz derecede güçlü ve yenilmez demektir. Kâinatta hiçbir varlık O'nun emir ve iradesine karşı koyamaz."},
    {u:"EK · 1. Yazılı Hazırlık", q:"Allah'ın dünyada mümin–kâfir, itaatkâr–günahkâr ayırmadan bütün varlıklara nimetlerinden vermesi hangi isminin göstergesidir?", o:["Selam","Kuddûs","Rahman","Aziz"], a:2,
     w:"Rahman ismi Allah'ın yarattığı bütün varlıklara rahmetinin göstergesidir."},
    {u:"EK · 1. Yazılı Hazırlık", q:"Müslümanların işe başlarken söylediği “Bismillâhirrahmânirrahîm” ifadesinde Allah'ın hangi ismi geçer?", o:["Aziz","Selam","Kerim","Rahman"], a:3,
     w:"Besmelede Rahman ismi geçer; Müslümanlar bu sözle Allah'ın şefkat ve merhametini isterler."},
    {u:"EK · 1. Yazılı Hazırlık", q:"Kitaba göre “Selamünaleyküm – Aleykümselam” sözlerinin anlamı nedir?", o:["Merhamet edenlere Allah da merhamet eder.","Selam sizin üzerinize olsun, Allah sizi her türlü kaza ve beladan korusun.","Allah sana uzun ömür ve bol rızık versin.","Allah'ın salat ve selamı onun üzerine olsun."], a:1,
     w:"Selamlaşma bir duadır; Selam ismini bilen Müslüman selamı insanlar arasında yayar (Nisa suresi 86)."},
    {u:"EK · 1. Yazılı Hazırlık", q:"Aziz ismini bilen bir Müslüman için aşağıdakilerden hangisi söylenebilir?", o:["Güçlü insanların her istediğini yapabileceğini düşünür.","Dua etmenin gereksiz olduğunu düşünür.","İyilikleri Allah'tan ister, sıkıntıda O'na sığınır.","Her şeyi kendi gücüyle başaracağını düşünür."], a:2,
     w:"Allah dilemedikçe kimseye fayda ya da zarar dokunmaz; O'nun dilediğine de kimse engel olamaz. Bunu bilen Müslüman iyilikleri Allah'tan ister, kötülük ve sıkıntılardan O'na sığınır."},
    {u:"EK · 1. Yazılı Hazırlık", q:"Selam ismini bilen bir Müslüman nasıl bir insan olmaya çalışır?", o:["Herkesin kendisinden emin olduğu, güvenilir biri","Kimseyle konuşmayan, içine kapanık biri","Yalnızca kendi işini düşünen biri","Herkesin kendisinden korktuğu biri"], a:0,
     w:"Selam esenlik ve güven veren demektir. Bu ismin bilincindeki Müslüman çevresine kötülük yapmaz, güvenilir olur ve selamlaşır."},
    {u:"EK · 2. Yazılı Hazırlık", q:"“… Allah tertemiz olanları sever.” (Tevbe suresi 108)\n\nBu ayete göre bir Müslüman niçin temiz olmalıdır?", o:["Allah'ın sevgisini kazanmak için","Başkalarına kendini beğendirmek için","Yalnızca hastalıklardan korunmak için","Sadece bayramlara hazırlanmak için"], a:0,
     w:"Ayet, Allah'ın temiz olanları sevdiğini bildirir. Müslüman bu sevgiyi kazanmak için bedenini, elbisesini, çevresini ve kalbini temiz tutar."},
    {u:"EK · 2. Yazılı Hazırlık", q:"“... Elbiseni temiz tut (nefsini arındır), günahlardan uzak dur.” (Müddessir suresi 4-5)\n\nBu ayetlerde aşağıdakilerden hangisine DEĞİNİLMEMİŞTİR?", o:["Elbisenin temiz tutulmasına","Nefsin arındırılmasına","Çevrenin temiz tutulmasına","Günahlardan uzak durulmasına"], a:2,
     w:"Ayetlerde elbiseyi temiz tutmak, nefsi arındırmak ve günahlardan uzak durmak emredilir. Çevre temizliğinden bu ayetlerde söz edilmez."},
    {u:"EK · 2. Yazılı Hazırlık", q:"Peygamberimiz çevresindeki insanlara temizlik alışkanlığı kazandırmaya çalışmış, “Temizlik imanın yarısıdır.” buyurmuştur.\n\nBu bilgilere göre aşağıdakilerden hangisi söylenebilir?", o:["Temizlik yalnızca ibadetten önce dikkat edilecek bir konudur.","Temizlik kişinin isteğine bırakılmış bir alışkanlıktır.","Temizlik dinî bir konu olmayıp yalnızca sağlıkla ilgilidir.","Temizlik Müslümanın hayatının vazgeçilmez bir parçasıdır."], a:3,
     w:"Hadis temizlik ile iman arasındaki bağa dikkat çeker. Temizlik bazı ibadetlerin şartı olduğu gibi Müslümanın hayatının da ayrılmaz bir parçasıdır ve Peygamberimiz bu konuda örnek olmuştur."},
    {u:"EK · 2. Yazılı Hazırlık", q:"Kitaptaki bilgi kutusuna göre “taharet” ve “nezafet” kelimeleri hangi kavramla aynı anlama gelir?", o:["İbadet","Temizlik","Tövbe","Cömertlik"], a:1,
     w:"Bilgi kutusuna göre taharet ve nezafet, temizlikle aynı anlama gelen kelimelerdir."},
    {u:"EK · 2. Yazılı Hazırlık", q:"İslam'da beden, çevre ve elbise temizliğinin yanında günahlardan kaçınmak ve kalbi kötü duygulardan uzak tutmak da temizliğin bir parçası sayılır.\n\nBu anlayışla ulaşılmak istenen hedef aşağıdakilerden hangisidir?", o:["Temiz, ahlaklı ve dürüst insanlardan oluşan bir toplum","Yalnızca sağlıklı bireylerden oluşan bir toplum","Herkesin aynı biçimde giyindiği bir toplum","Temizlik işlerinin tek kişiye bırakıldığı bir toplum"], a:0,
     w:"Dinimiz insanın madden ve manen temiz olmasını ister. Böylece temiz, ahlaklı ve dürüst insanlardan oluşan bir toplum hedeflenir."},
    {u:"EK · 2. Yazılı Hazırlık", q:"I. Dişleri fırçalamak\nII. Gusül almak\nIII. Kıskandığı için pişman olup tövbe etmek\n\nBu davranışlar sırasıyla hangi temizlik çeşitlerine örnektir?", o:["Hükmi – maddi – manevi","Maddi – manevi – hükmi","Maddi – hükmi – manevi","Manevi – hükmi – maddi"], a:2,
     w:"Diş fırçalamak beden temizliği olduğu için maddi, gusül abdestsizlik hâlinden arınma olduğu için hükmi, tövbe kalbi kötü duygulardan arındırdığı için manevi temizliktir."},
    {u:"EK · 2. Yazılı Hazırlık", q:"İbadetlere engel olan abdestsizlik hâlinden abdest veya gusül alarak temizlenmeye ne ad verilir?", o:["Necasetten taharet","Manevi temizlik","Mest üzerine mesh","Hadesten taharet"], a:3,
     w:"Abdestsizlik hâline hades denir. Bu hâlden abdest ve gusülle arınmaya hadesten taharet denir."},
    {u:"EK · 2. Yazılı Hazırlık", q:"Peygamberimiz “… Evlerinizin önlerini temiz tutun.” buyurmuştur.\n\nBu hadis en çok hangi temizlikle ilgilidir?", o:["Çevre temizliği","Ağız ve diş temizliği","Elbise temizliği","Kalp temizliği"], a:0,
     w:"Çevre temizliği ev, okul, sokak gibi yaşadığımız yerleri ve orman, deniz, göl gibi doğal alanları kapsar. Çevre Allah'ın bize emanetidir."},
    {u:"EK · 2. Yazılı Hazırlık", q:"“Allah sizin suretlerinize ve mallarınıza bakmaz ancak kalplerinize ve amellerinize bakar.”\n\nBu hadisten hangi sonuç çıkarılabilir?", o:["Dış görünüşe ve giyime hiç özen göstermek gerekmez.","Malı çok olan kişi Allah katında daha değerlidir.","Asıl değer, kalbin ve davranışların temizliğindedir.","Güzel görünen kişinin kalbi de mutlaka temiz olur."], a:2,
     w:"Hadis, Allah'ın insanları kalplerindeki duygu ve düşüncelere ve yaptıkları işlere göre değerlendirdiğini gösterir. Bu yüzden kalbimizi kötülüklerden uzak tutup güzel ahlakla doldurmalıyız."},
    {u:"EK · 2. Yazılı Hazırlık", q:"İbadet, kulun Rabbi ile buluşmasıdır. Sevdiğimiz birinin karşısına çıkarken nasıl özen gösteriyorsak Allah'ın huzuruna çıkarken de hazırlanmalıyız.\n\nBuna göre ibadete hazırlanan bir Müslüman için aşağıdakilerden hangisi SÖYLENEMEZ?", o:["Bedenini ve giysisini her türlü kirden temizler.","İbadet edeceği yeri kirden arındırır.","Kalbini kötü duygulardan arındırır.","Yalnızca kıyafetinin görünüşüne önem verir."], a:3,
     w:"İbadetten önce beden, giysi ve ibadet yeri kirden arındırılır, kalp de kötü duygu ve düşüncelerden temizlenir. Yalnızca dış görünüşe önem vermek bu hazırlık için yeterli olmaz."},
    {u:"EK · 2. Yazılı Hazırlık", q:"“...Başlarınızı mesh edin, ayaklarınızı da topuk kemiklerine kadar yıkayın...” (Maide suresi 6)\n\nBu ayete göre abdestte yıkanmayıp mesh edilen organ hangisidir?", o:["Yüz","Baş","Kollar","Ayaklar"], a:1,
     w:"Ayette baş için “mesh edin” denir. Abdestte başın dörtte birini mesh etmek farzdır."},
    {u:"EK · 2. Yazılı Hazırlık", q:"Abdest alan Can niyet edip euzübesmele çektikten sonra ellerini bileklere kadar yıkadı, ağzına ve burnuna su verdi, yüzünü yıkadı.\n\nCan'ın bundan sonra yapması gereken hangisidir?", o:["Kollarını dirseklerle birlikte yıkamak","Başının dörtte birini mesh etmek","Ayaklarını topuklarla birlikte yıkamak","Kulaklarını temizleyip ensesini mesh etmek"], a:0,
     w:"Abdestte yüz yıkandıktan sonra önce sağ, sonra sol kol dirseklerle birlikte üç kez yıkanır."},
    {u:"EK · 2. Yazılı Hazırlık", q:"Zeynep abdest aldıktan sonra yatağına uzanıp uyudu. Uyandığında Kur'an okumak istedi.\n\nZeynep için aşağıdakilerden hangisi doğrudur?", o:["Abdesti bozulmamıştır, Kur'an'ı okuyabilir.","Yalnızca ellerini yıkaması yeterlidir.","Abdesti bozulmuştur, yeniden abdest almalıdır.","Su varken de teyemmüm ederek okuyabilir."], a:2,
     w:"Uyku, iradenin kontrolünde olmayan bir durumdur ve abdesti bozar. Kur'an okumak için abdestli olmak gerekir."},
    {u:"EK · 2. Yazılı Hazırlık", q:"Bir sahabi Peygamberimize “Abdestte israf olur mu?” diye sormuş, Peygamberimiz “Evet, akan bir nehir üzerinde bile olsan (abdestte israf vardır).” cevabını vermiştir.\n\nBu hadisten çıkarılabilecek sonuç hangisidir?", o:["Abdest yalnızca nehir kenarında alınmalıdır.","Su bol olsa bile abdestte israf edilmemelidir.","Abdestte su ne kadar çok kullanılırsa o kadar iyidir.","İsraf yalnızca yiyecek ve içecekte olur."], a:1,
     w:"Dinimizde her türlü israf yasaktır. Su bol olduğu yerde bile abdest alırken suyu gereğinden fazla kullanmamalıyız."},
    {u:"EK · 2. Yazılı Hazırlık", q:"Peygamberimiz “Her kim abdest alır ve de abdestini güzelce almaya özen gösterirse günahları vücudundan çıkar, hatta tırnaklarının altından süzülür gider.” buyurmuştur.\n\nBu hadis abdestin hangi yönünü öne çıkarır?", o:["Mikroplardan korumasını","Vücudu dinlendirip rahatlatmasını","Uykuyu açmasını","Günahlardan arındırmasını"], a:3,
     w:"Abdest beden temizliği sağlamanın yanında insanı ibadete hazırlar ve günahlarından arındırır."},
    {u:"EK · 2. Yazılı Hazırlık", q:"Peygamberimiz “Her yedi günde bir yıkanmak, Yüce Allah'ın her Müslüman üzerindeki hakkıdır.” buyurmuştur.\n\nBu hadisle Müslümanlara ne tavsiye edilmiştir?", o:["Haftada en az bir kez boy abdesti almak","Yalnızca bayram sabahlarında boy abdesti almak","Her gün yedi kez abdest tazelemek","Haftada bir gün evini temizlemek"], a:0,
     w:"Peygamberimiz bu sözle Müslümanlara haftada en az bir kez boy abdesti almayı tavsiye etmiştir. Bu yıkanma insanı ibadete hazır hâle getirir."},
    {u:"EK · 2. Yazılı Hazırlık", q:"“…Eğer cünüp iseniz iyice yıkanarak temizlenin…” (Maide suresi 6)\n\nBu ayette hangi temizlik emredilmektedir?", o:["Teyemmüm","Mest üzerine mesh","Gusül","Ağız ve diş temizliği"], a:2,
     w:"Ayetteki “iyice yıkanarak temizlenme” emri guslü, yani boy abdestini anlatır. Gusül, akıllı ve ergenlik çağındaki her Müslümanın bazı özel durumlarda alması şart olan bir temizliktir."},
    {u:"EK · 2. Yazılı Hazırlık", q:"Abdest, gusül ve teyemmümün farzları karşılaştırıldığında aşağıdakilerden hangisi söylenebilir?", o:["Abdestin farzı üç, guslün farzı dörttür.","Ağzı ve burnu yıkamak guslün farzıdır, abdestin değil.","Teyemmümde yüz ve kollar toprakla değil suyla yıkanır.","Gusülde baş yıkanmaz, yalnızca mesh edilir."], a:1,
     w:"Ağzı ve burnu yıkamak guslün farzlarındandır. Abdestte ağza ve burna su verilir ama bunlar abdestin dört farzı arasında yer almaz."},
    {u:"EK · 2. Yazılı Hazırlık", q:"Aşağıdakilerden hangisi teyemmümün farzlarından biridir?", o:["Ağzı ve burnu yıkamak","Başın dörtte birini mesh etmek","Ayakları topuklarla yıkamak","Niyet etmek"], a:3,
     w:"Teyemmümün farzı ikidir: niyet etmek ve elleri temiz toprağa sürerek yüzü ve kolları mesh etmek."},
    {u:"EK · 2. Yazılı Hazırlık", q:"Aşağıdaki durumların hangisinde teyemmüm yapılabilir?", o:["Su bulunmayan bir yolculukta","Abdest suyu varken acele edilen bir anda","Abdest almaya üşenildiğinde","Su varken zaman kazanmak istendiğinde"], a:0,
     w:"Teyemmüm suyun bulunmadığı, soğuktan dolayı kullanılamadığı ya da hastalık ve can güvenliği açısından tehlikeli olduğu durumlarda yapılır. Acele etmek ve üşenmek bu durumlar arasında yer almaz."},
    {u:"EK · 2. Yazılı Hazırlık", q:"Hastalığı yüzünden suyu kullanamadığı için teyemmüm eden Ali iyileşti ve suyu kullanabilir hâle geldi.\n\nAli'nin teyemmümü için ne söylenebilir?", o:["Teyemmümü bir gün boyunca geçerlidir.","İyileşmiş olsa da teyemmümü bozulmaz.","Teyemmümü bozulmuştur, abdest almalıdır.","Yalnızca ellerini suyla yıkaması yeterlidir."], a:2,
     w:"Teyemmümü gerektiren özrün ortadan kalkması teyemmümü bozar. Ali artık suyu kullanabildiği için abdest almalıdır."},
    {u:"EK · 2. Yazılı Hazırlık", q:"Kerim isminin anlamı aşağıdakilerden hangisidir?", o:["Her türlü eksiklikten ve hatadan uzak, kemal ve güzellik sahibi","Nimetlerini karşılıksız veren, cömert ve en şerefli","Kullarının tövbelerini çokça kabul eden, onları bağışlayan","Güç, kuvvet ve şeref sahibi, her şeye galip gelen"], a:1,
     w:"Kerim sözlükte cömert ve şerefli olmak demektir. Allah mümin–kâfir ayırt etmeden bütün kullarına sayısız ikramda bulunur ve karşılık beklemez."},
    {u:"EK · 2. Yazılı Hazırlık", q:"“... Ey kendi aleyhlerine olarak günahta haddi aşan kullarım! Allah'ın rahmetinden ümit kesmeyin. Allah (dilerse) bütün günahları bağışlar...” (Zümer suresi 53)\n\nBu ayete göre hata yapan bir Müslüman ne yapmalıdır?", o:["Hata yaptığı için ibadeti bırakmalıdır.","Hatasını kimse bilmiyorsa önemsememelidir.","Bağışlanmayacağını düşünüp yalnızca üzülmelidir.","Rahmetten ümit kesmeden Allah'tan af dilemelidir."], a:3,
     w:"Allah kullarını bağışlamada kerem sahibidir. Hata ve günahlarımız için O'ndan samimiyetle af dilememizi ve rahmetine sığınmamızı ister."},
    {u:"EK · 2. Yazılı Hazırlık", q:"Kuddûs isminin anlamını kavrayan bir Müslüman için aşağıdakilerden hangisi söylenebilir?", o:["Kusurlarını gizleyip hiç hata yapmadığını söyler.","Tövbeyle arınıp saf ve temiz olmaya çalışır.","Yalnızca dış görünüşünün temiz olmasına önem verir.","Başkalarının kusurlarını araştırıp herkese anlatır."], a:1,
     w:"Peygamberimiz “Ey insanlar! Allah temizdir ancak temiz olan şeyleri kabul eder...” buyurmuştur. Bu öğüdü örnek alan Müslüman günahlardan tövbeyle arınmaya, saf ve temiz olmaya özen gösterir."},
    {u:"EK · 2. Yazılı Hazırlık", q:"Tevvâb isminin sözlük anlamı aşağıdakilerden hangisidir?", o:["Güç ve kuvvet sahibi","Her varlığa merhamet eden","Dönüş yapan","Güven, esenlik, huzur"], a:2,
     w:"Tevvâb kelimesi sözlükte dönüş yapan anlamına gelir. Güç ve kuvvet Aziz, merhamet Rahman, güven ve esenlik Selam isimleriyle ilgilidir."}
  ];
